<template>
  <div
    class="q-pa-md"
    v-if="
      selectedRule &&
      Object.keys(selectedRule).length > 0 &&
      selectedRule.match_criteria
    "
  >
    <p class="text-weight-bold text-primary font-size-16">
      {{ $t('criteria') }}
    </p>
    <div class="row q-gutter-md">
      <q-select
        :disable="isDefault"
        outlined
        dense
        emit-value
        map-options
        class="criteria-select"
        v-model="unit_price_select"
        :options="unit_price_options"
      >
        <template v-slot:option="scope">
          <q-item v-bind="scope.itemProps">
            <q-item-section>
              <q-item-label>{{ $t(scope.opt.label) }}</q-item-label>
            </q-item-section>
          </q-item>
        </template>
        <template v-slot:selected-item="scope">
          <div>{{ $t(scope.opt.label) }}</div>
        </template>
      </q-select>

      <q-select
        :disable="isDefault"
        outlined
        dense
        emit-value
        map-options
        class="criteria-select"
        v-model="comparisonType"
        :options="comparisonTypeList"
        :label="$t('comparison_type')"
      />

      <q-select
        :disable="isDefault"
        outlined
        dense
        emit-value
        map-options
        class="criteria-select"
        v-model="comparison_select"
        :options="comparison_options"
        :label="$t('comparison_operator')"
      >
      </q-select>

      <q-input
        :disable="isDefault"
        :label="$t('value')"
        type="number"
        v-model.number="value"
        outlined
        dense
        class="criteria-select"
        v-if="
          comparison_select != 'outside_tolerance' &&
          comparison_select != 'within_tolerance'
        "
      />

      <q-select
        :disable="isDefault"
        outlined
        dense
        emit-value
        map-options
        class="criteria-select"
        v-model="status_select"
        :options="status_options"
        v-if="comparison_select == 'outside_tolerance'"
        :label="$t('status')"
      >
      </q-select>

      <template v-if="selectedIndex >= 0">
        <f-btn
          :disable="isDefault"
          :label="$t('update')"
          @click="updateCriteria()"
        />
        <f-btn
          :disable="isDefault"
          :label="$t('cancel')"
          @click="resetModel()"
        />
      </template>
      <f-btn
        v-else
        :disable="isDefault"
        :label="$t('add_criteria')"
        @click="addCriteria()"
      />
    </div>

    <q-markup-table
      flat
      class="dashboard-table-style dashboard-table-height back-white q-mt-lg"
    >
      <thead>
        <tr class="table-header-text">
          <th>
            {{ $t('active') }}
          </th>
          <th>
            {{ $t('unit_price_quantity') }}
          </th>
          <th>
            {{ $t('comparison_type') }}
          </th>
          <th>
            {{ $t('comparison_operator') }}
          </th>
          <th>
            {{ $t('value') }}
          </th>
          <th>
            {{ $t('approved') }}
          </th>
          <th style="width: 100px">
            {{ $t('actions') }}
          </th>
        </tr>
      </thead>
      <tbody>
        <tr
          v-for="(criteria, index) in selectedRule.match_criteria"
          :key="index"
          @click="criteriaClicked(criteria, index)"
          class="cursor-pointer"
          :class="selectedIndex == index ? 'highlighted-back' : ''"
        >
          <td>
            <q-checkbox
              dense
              v-model="criteria['active']"
              :disable="isDefault"
            />
          </td>
          <td>{{ $t(criteria.column) }}</td>
          <td>
            {{ criteria.comparison_type ? $t(criteria.comparison_type) : '' }}
          </td>
          <td>
            {{
              criteria.comparison_operator
                ? $t(criteria.comparison_operator)
                : ''
            }}
          </td>
          <td>{{ criteria.value }}</td>
          <td>{{ criteria.approved }}</td>
          <td>
            <q-btn flat dense round @click.stop.prevent icon="more_horiz">
              <q-menu
                auto-close
                transition-show="jump-down"
                transition-hide="jump-up"
                anchor="bottom middle"
                self="top middle"
              >
                <q-list dense style="min-width: 100px">
                  <!-- <q-item clickable @click="editEvent()">
                        <q-item-section>Bearbeiten</q-item-section>
                    </q-item>
                    <q-separator inset /> -->
                  <q-item
                    clickable
                    @click="removeCriteria(index)"
                    :disable="isDefault"
                  >
                    <q-item-section
                      ><span class="text-red-14">{{ $t('delete') }}</span>
                    </q-item-section>
                  </q-item>
                </q-list>
              </q-menu>
            </q-btn>
          </td>
        </tr>
      </tbody>
    </q-markup-table>
  </div>

  <q-separator class="q-my-md" v-if="showActionPanel" />
  <div class="q-pa-md row" v-if="showActionPanel">
    <div class="col-6">
      <p class="text-weight-bold text-primary font-size-16 q-pb-md">
        {{ $t('test_rules') }}
      </p>
      <div class="">
        <div class="q-gutter-md">
          <q-input
            :disable="isDefault"
            :label="$t('po_quantity')"
            v-model="test_rules_input['po_quantity']"
            outlined
            dense
            class="test-rules-input"
          />
          <q-input
            :disable="isDefault"
            :label="$t('po_unit_price')"
            v-model="test_rules_input['po_unit_price']"
            outlined
            dense
            class="test-rules-input"
          />
          <q-input
            :disable="isDefault"
            :label="$t('invoice_quantity')"
            v-model="test_rules_input['invoice_quantity']"
            outlined
            dense
            class="test-rules-input"
          />
          <q-input
            :disable="isDefault"
            :label="$t('invoice_unit_price')"
            v-model="test_rules_input['invouce_unit_price']"
            outlined
            dense
            class="test-rules-input"
          />
          <f-btn :label="$t('test')" @click="testRules" />
        </div>
      </div>
    </div>

    <div class="col-6">
      <p class="text-weight-bold text-primary font-size-16">
        {{ $t('output') }}
      </p>
      <div class="row">
        <q-input
          :disable="isDefault"
          v-model="test_rules_output"
          readonly
          outlined
          type="textarea"
          class="test-rules-input"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { useRuleManagerStore } from 'src/store/main';
export default defineComponent({
  name: 'MatchCriteria',
  mixins: [helperMixin],
  emits: ['updateToml'],
  props: {
    isDefault: {
      type: Boolean,
      default: false,
    },
  },
  mounted() {
    this.initDropDowns();
  },
  methods: {
    addCriteria() {
      const criteria: any = {
        column: this.unit_price_select,
        comparison_type: this.comparisonType,
        comparison_operator: this.comparison_select,
        approved: this.getApproved(),
        value: this.getValue(),
        active: true,
      };
      this.selectedRule.match_criteria.push(criteria);
      this.$emit('updateToml');
      this.resetModel();
    },
    updateCriteria() {
      if (this.selectedIndex < 0) {
        return;
      }

      this.selectedRule.match_criteria[this.selectedIndex].column =
        this.unit_price_select;
      this.selectedRule.match_criteria[this.selectedIndex].comparison_type =
        this.comparisonType;
      this.selectedRule.match_criteria[this.selectedIndex].comparison_operator =
        this.comparison_select;
      this.selectedRule.match_criteria[this.selectedIndex].approved =
        this.getApproved();
      this.selectedRule.match_criteria[this.selectedIndex].value =
        this.getValue();

      this.$emit('updateToml');
      this.resetModel();
    },
    resetModel() {
      this.value = null;
      this.status_select = 'true';
      this.comparison_select = 'equal';
      this.unit_price_select = 'quantity';
      this.comparisonType = 'difference';

      this.selectedCriteria = null;
      this.selectedIndex = -1;
    },
    getValue(): any {
      if (
        this.comparison_select == 'outside_tolerance' ||
        this.comparison_select == 'within_tolerance'
      ) {
        return null;
      }
      return this.value.toString();
    },
    getApproved(): any {
      if (this.comparison_select == 'outside_tolerance') {
        return this.status_select;
      }
      return null;
    },
    removeCriteria(index: number) {
      this.selectedRule.match_criteria.splice(index, 1);
      this.$emit('updateToml');
    },
    criteriaClicked(criteria: any, index: number) {
      this.selectedCriteria = criteria;
      this.selectedIndex = index;
      this.preapreUpdateModel();
      //   this.showActionPanel = true;
    },
    preapreUpdateModel() {
      if (!this.selectedCriteria) {
        return;
      }

      this.value = this.selectedCriteria.value;
      this.status_select = this.selectedCriteria.approved;
      this.comparisonType = this.selectedCriteria.comparison_type;
      this.comparison_select = this.selectedCriteria.comparison_operator;
      this.unit_price_select = this.selectedCriteria.column;
    },
    testRules() {
      notify.success('Test Rules');
    },
    initDropDowns() {
      this.comparisonTypeList = [
        {
          label: this.$t('difference'),
          value: 'difference',
        },
        {
          label: this.$t('value'),
          value: 'value',
        },
      ];

      this.status_options = [
        {
          label: this.$t('approved'),
          value: 'true',
        },
        {
          label: this.$t('rejected'),
          value: 'false',
        },
      ];

      this.comparison_options = [
        {
          label: this.$t('equal'),
          value: 'equal',
        },
        {
          label: this.$t('greater_than'),
          value: 'greater_than',
        },
        {
          label: this.$t('greater_than_or_equal_to'),
          value: 'greater_than_or_equal_to',
        },
        {
          label: this.$t('less_than'),
          value: 'less_than',
        },
        {
          label: this.$t('less_than_or_equal_to'),
          value: 'less_than_or_equal_to',
        },
        {
          label: this.$t('within_tolerance'),
          value: 'within_tolerance',
        },
        {
          label: this.$t('outside_tolerance'),
          value: 'outside_tolerance',
        },
      ];
    },
  },
  setup() {
    const rule_manager_store = useRuleManagerStore();
    const { selectedRule } = storeToRefs(rule_manager_store);

    return {
      selectedRule,
      value: ref(),
      selectedCriteria: ref({} as any),
      selectedIndex: ref(-1),
      showActionPanel: ref(false),
      status_select: ref('true'),
      comparison_select: ref('equal'),
      unit_price_select: ref('quantity'),
      test_rules_output: ref(''),
      test_rules_input: ref({
        po_quantity: '',
        po_unit_price: '',
        invoice_quantity: '',
        invouce_unit_price: '',
      }),
      comparisonType: ref('difference'),
      comparisonTypeList: ref([] as any),
      status_options: ref([] as any),
      comparison_options: ref([] as any),
      unit_price_options: [
        {
          label: 'quantity',
          value: 'quantity',
        },
        {
          label: 'unit_price',
          value: 'unit_price',
        },
        {
          label: 'charge_rate',
          value: 'charge_rate',
        },
        {
          label: 'charge_per_unit',
          value: 'charge_per_unit',
        },
      ],
    };
  },
});
</script>

<style scoped>
.criteria-select {
  min-width: 18%;
}
</style>
