<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { useRuleManagerStore } from 'src/store/main';

export default defineComponent({
  name: 'actions',
  mixins: [helperMixin],
  emits: ['updateToml'],
  props: {
    isDefault: {
      type: Boolean,
      default: false,
    },
  },
  mounted() {
    this.initDropDowns();
  },
  methods: {
    resetModel(resetActionTypeSelect: boolean) {
      if (resetActionTypeSelect) {
        this.conditionExpression = '';
        this.addConditionExpression = false;
        this.action_type_select = 'receipt_line';
      }

      this.value = '';
      this.amount = '';
      this.pattern = '';
      this.sequence = '';
      this.dimension_1 = '';
      this.dimension_2 = '';
      this.dimension_3 = '';
      this.dimension_4 = '';
      this.dimension_5 = '';
      this.dimension_6 = '';
      this.dimension_7 = '';
      this.voucher_text = '';
      this.ledger_account = '';
      this.customSequence = '';
      this.costing_element = '';
      this.quantity_select = '';
      this.unit_price_select = '';

      if (
        this.action_type_select.includes('line_charge') ||
        this.action_type_select.includes('receipt_line')
      ) {
        // select first element
        this.quantity_select = '[po_quantity]';
        this.unit_price_select = '[po_unit_price]';
      }

      if (
        this.action_type_select.includes('line_charge') ||
        this.action_type_select.includes('header_charge')
      ) {
        // select first element
        this.sequence = 'original';
        this.costing_element = 'original';
      }
    },
    resetAll() {
      this.resetModel(true);
      this.selectedIndex = -1;
      this.selectedAction = null;
    },
    addActions() {
      const action = this.prepareactionObj();
      this.selectedRule.actions.push(action);
      this.$emit('updateToml');
      this.resetAll();
    },
    updateActions() {
      if (this.selectedIndex < 0) {
        return;
      }
      const action = this.prepareactionObj();
      this.selectedRule.actions[this.selectedIndex] = action;
      this.$emit('updateToml');
      this.resetAll();
    },
    prepareactionObj(): any {
      const mapping = {} as any;

      if (this.quantity_select) {
        mapping['quantity'] = this.quantity_select;
      }

      if (this.unit_price_select) {
        mapping['unit_price'] = this.unit_price_select;
      }

      if (this.getSequence()) {
        mapping['sequence'] = this.getSequence();
      }

      if (this.getCostingElement()) {
        mapping['costing_element'] = this.getCostingElement();
      }

      if (this.amount) {
        mapping['amount'] = this.amount;
      }

      if (this.ledger_account) {
        mapping['ledger_account'] = this.ledger_account;
      }

      if (this.voucher_text) {
        mapping['voucher_text'] = this.voucher_text;
      }

      if (this.dimension_1) {
        mapping['dimension_1'] = this.dimension_1;
      }

      if (this.dimension_2) {
        mapping['dimension_2'] = this.dimension_2;
      }

      if (this.dimension_3) {
        mapping['dimension_3'] = this.dimension_3;
      }

      if (this.dimension_4) {
        mapping['dimension_4'] = this.dimension_4;
      }

      if (this.dimension_5) {
        mapping['dimension_5'] = this.dimension_5;
      }

      if (this.dimension_6) {
        mapping['dimension_6'] = this.dimension_6;
      }

      if (this.dimension_7) {
        mapping['dimension_7'] = this.dimension_7;
      }

      const action: any = {
        type: this.action_type_select,
        mapping: mapping,
      };

      if (this.conditionExpression) {
        action['condition_expression'] = this.conditionExpression;
      }

      return action;
    },
    getSequence() {
      if (
        !this.action_type_select.includes('line_charge') &&
        !this.action_type_select.includes('header_charge')
      ) {
        return null;
      }

      if (this.sequence == 'custom') {
        return this.customSequence;
      }

      return this.sequence;
    },
    getCostingElement() {
      if (
        !this.action_type_select.includes('line_charge') &&
        !this.action_type_select.includes('header_charge')
      ) {
        return null;
      }

      if (this.costing_element == 'custom') {
        return this.value;
      }

      if (this.costing_element == 'regex') {
        return this.costing_element + ':' + this.pattern + ':' + this.value;
      }

      return this.costing_element;
    },
    setActiveAction(actionObj: any, index: number) {
      // clear old selection
      this.resetModel(true);

      this.selectedIndex = index;
      this.selectedAction = actionObj;

      if (!this.selectedAction || !this.selectedAction.mapping) {
        return;
      }

      // load model
      this.action_type_select = this.selectedAction.type;

      this.amount = this.selectedAction.mapping.amount;
      this.ledger_account = this.selectedAction.mapping.ledger_account;
      this.voucher_text = this.selectedAction.mapping.voucher_text;
      this.dimension_1 = this.selectedAction.mapping.dimension_1;
      this.dimension_2 = this.selectedAction.mapping.dimension_2;
      this.dimension_3 = this.selectedAction.mapping.dimension_3;
      this.dimension_4 = this.selectedAction.mapping.dimension_4;
      this.dimension_5 = this.selectedAction.mapping.dimension_5;
      this.dimension_6 = this.selectedAction.mapping.dimension_6;
      this.dimension_7 = this.selectedAction.mapping.dimension_7;
      this.quantity_select = this.selectedAction.mapping.quantity;
      this.unit_price_select = this.selectedAction.mapping.unit_price;

      this.conditionExpression = this.selectedAction.condition_expression;
      if (this.conditionExpression) {
        this.addConditionExpression = true;
      }

      if (this.selectedAction.mapping.sequence) {
        this.sequence = this.selectedAction.mapping.sequence;
        const isSequenceFound = this.findField(
          this.sequence,
          this.sequenceOptions,
        );

        if (!isSequenceFound) {
          this.customSequence = this.selectedAction.mapping.sequence;
          this.sequence = 'custom';
        }
      }

      if (this.selectedAction.mapping.costing_element) {
        this.costing_element = this.selectedAction.mapping.costing_element;
        const isCostingElementFound = this.findField(
          this.costing_element,
          this.costingElementOptions,
        );

        if (!isCostingElementFound) {
          if (this.costing_element.includes(':')) {
            let elements = this.costing_element.split(':');
            if (elements[0]) {
              this.costing_element = elements[0];
            }

            if (elements[1]) {
              this.pattern = elements[1];
            }

            if (elements[2]) {
              this.value = elements[1];
            }
          } else {
            this.value = this.selectedAction.mapping.costing_element;
            this.costing_element = 'custom';
          }
        }
      }
    },
    findField(fieldName: string, sourceDropdown: any) {
      let isFound = false;
      for (let item of sourceDropdown) {
        if (item.value == fieldName) {
          isFound = true;
        }
      }

      return isFound;
    },
    removeActions(index: number) {
      this.selectedRule.actions.splice(index, 1);
      this.$emit('updateToml');
    },
    selectQuantity(value: string) {
      this.quantity_select += value;
    },
    selectUnitPrice(value: string) {
      this.unit_price_select += value;
    },
    selectConditionExpression(value: string) {
      this.conditionExpression += value;
    },
    selectAmount(value: string) {
      this.amount += value;
    },
    initDropDowns() {
      this.costingElementOptions = [
        {
          label: this.$t('original'),
          value: 'original',
        },
        {
          label: this.$t('regex_replace'),
          value: 'regex',
        },
        {
          label: this.$t('mapped'),
          value: 'mapped',
        },
        {
          label: this.$t('custom'),
          value: 'custom',
        },
      ];
      this.sequenceOptions = [
        {
          label: this.$t('original'),
          value: 'original',
        },
        {
          label: this.$t('increment'),
          value: 'increment',
        },
        {
          label: this.$t('decrement'),
          value: 'decrement',
        },
        {
          label: this.$t('mapped'),
          value: 'mapped',
        },
        {
          label: this.$t('custom'),
          value: 'custom',
        },
      ];
      this.actionTypeOptions = [
        {
          label: this.$t('receipt_line'),
          value: 'receipt_line',
        },
        {
          label: this.$t('cost_line'),
          value: 'cost_line',
        },
        {
          label: this.$t('header_charge'),
          value: 'header_charge',
        },
        {
          label: this.$t('line_charge'),
          value: 'line_charge',
        },
        {
          label: this.$t('tax_line'),
          value: 'tax_line',
        },
        {
          label: this.$t('debit_note_receipt_line'),
          value: 'debit_note_receipt_line',
        },
        {
          label: this.$t('debit_note_cost_line'),
          value: 'debit_note_cost_line',
        },
        {
          label: this.$t('debit_note_header_charge'),
          value: 'debit_note_header_charge',
        },
        {
          label: this.$t('debit_note_line_charge'),
          value: 'debit_note_line_charge',
        },
        {
          label: this.$t('debite_note_tax_line'),
          value: 'debite_note_tax_line',
        },
        {
          label: this.$t('credit_note_receipt_line'),
          value: 'credit_note_receipt_line',
        },
        {
          label: this.$t('credit_note_cost_line'),
          value: 'credit_note_cost_line',
        },
        {
          label: this.$t('credit_note_header_charge'),
          value: 'credit_note_header_charge',
        },
        {
          label: this.$t('credit_note_line_charge'),
          value: 'credit_note_line_charge',
        },
        {
          label: this.$t('credit_note_tax_line'),
          value: 'credit_note_tax_line',
        },
        {
          label: this.$t('quote_line'),
          value: 'quote_line',
        },
      ];

      this.fieldsOptions = [
        {
          label: 'po_unit_price',
          value: '[po_unit_price]',
        },
        {
          label: 'invoice_unit_price',
          value: '[invoice_unit_price]',
        },
        {
          label: 'approved_unit_price',
          value: '[approved_unit_price]',
        },
        {
          label: 'rejected_unit_price',
          value: '[rejected_unit_price]',
        },
        {
          label: 'po_quantity',
          value: '[po_quantity]',
        },
        {
          label: 'invoice_quantity',
          value: '[invoice_quantity]',
        },
        {
          label: 'approved_quantity',
          value: '[approved_quantity]',
        },
        {
          label: 'rejected_quantity',
          value: '[rejected_quantity]',
        },
        {
          label: 'po_amount',
          value: '[po_amount]',
        },
        {
          label: 'invoice_amount',
          value: '[invoice_amount]',
        },
        {
          label: 'expected_amount',
          value: '[expected_amount]',
        },
        {
          label: 'approved_amount',
          value: '[approved_amount]',
        },
        {
          label: 'po_charge_rate',
          value: '[po_charge_rate]',
        },
        {
          label: 'invoice_charge_rate',
          value: '[invoice_charge_rate]',
        },
        {
          label: 'approved_charge_rate',
          value: '[approved_charge_rate]',
        },
        {
          label: 'po_charge_unit_price',
          value: '[po_charge_unit_price]',
        },
        {
          label: 'invoice_charge_unit_price',
          value: '[invoice_charge_unit_price]',
        },
        {
          label: 'approved_charge_unit_price',
          value: '[approved_charge_unit_price]',
        },
        {
          label: 'po_charge_amount',
          value: '[po_charge_amount]',
        },
        {
          label: 'expected_charge_amount',
          value: '[expected_charge_amount]',
        },
        {
          label: 'invoice_charge_amount',
          value: '[invoice_charge_amount]',
        },
        {
          label: 'approved_charge_amount',
          value: '[approved_charge_amount]',
        },
      ];
    },
  },
  setup() {
    const rule_manager_store = useRuleManagerStore();
    const { selectedRule } = storeToRefs(rule_manager_store);
    return {
      selectedRule,
      value: ref(''),
      amount: ref(''),
      pattern: ref(''),
      customSequence: ref(''),
      sequence: ref('original'),
      costing_element: ref('original'),
      quantity_select: ref('[po_quantity]'),
      quantitySelect: ref([]),
      action_type_select: ref('receipt_line'),
      unit_price_select: ref('[po_unit_price]'),
      ledger_account: ref(''),
      voucher_text: ref(''),
      dimension_1: ref(''),
      dimension_2: ref(''),
      dimension_3: ref(''),
      dimension_4: ref(''),
      dimension_5: ref(''),
      dimension_6: ref(''),
      dimension_7: ref(''),
      fieldsOptions: ref([] as any),
      sequenceOptions: ref([] as any),
      actionTypeOptions: ref([] as any),
      costingElementOptions: ref([] as any),
      addConditionExpression: ref(false),
      conditionExpression: ref(''),
      selectedAction: ref({} as any),
      selectedIndex: ref(-1),
    };
